-- ============================================================
-- تفصيل النتائج حسب المكاتب الفرعية (محاضر حقيقية) — جماعة تطوان،
-- دائرة تطوان، انتخابات 23 شتنبر 2026. طلب علي (25 شتنبر 2026): تفصيل
-- حسب المكاتب الفرعية فصفحة /results الحية، ماشي غير ملف Excel.
--
-- المصدر: TETOUAN_LOCAL_LIST_RESULTS_BY_POLLING_OFFICE_2026_v1.1.xlsx
-- (محاضر حقيقية جابوها المراقبون من 84 مكتبا فرعيا بجماعة تطوان،
-- 9 لوائح فقط مذكورة فالمحضر الأصلي، من ضمنها "زهير الركاني — PPS").
-- هاد الجدول فيه بيانات حقيقية (ماشي تقديرية) على مستوى المكتب
-- الفرعي، بعكس election_results اللي كيبقى تقدير على مستوى المكتب
-- المركزي مبني على اللائحة الجهوية.
--
-- الربط بـpolling_stations كيتم وقت القراءة (فـelectionResults.ts)
-- عبر (commune='تطوان', sub_office_number=office_number) — مطابقة
-- دقيقة بالرقم، ماشي بالاسم. صفين ماعندهمش رقم مكتب صريح فالمحضر
-- الأصلي ("غير محدد") محفوظين بـoffice_number=null وoffice_number_raw
-- لتوضيح الحالة، وكيبانو فصفحة النتائج كصفوف غير قابلة للربط.
-- ============================================================

create table if not exists public.sub_office_election_results (
  id uuid primary key default gen_random_uuid(),
  commune_name text not null,
  office_number integer,
  office_number_raw text,
  party_votes jsonb not null default '{}'::jsonb,
  total_votes integer,
  created_at timestamptz not null default now()
);
create index if not exists sub_office_election_results_office_idx
  on public.sub_office_election_results (commune_name, office_number);

alter table public.sub_office_election_results enable row level security;
drop policy if exists "authenticated read sub_office_election_results" on public.sub_office_election_results;
create policy "authenticated read sub_office_election_results" on public.sub_office_election_results
  for select using (auth.role() = 'authenticated');
drop policy if exists "editors write sub_office_election_results" on public.sub_office_election_results;
create policy "editors write sub_office_election_results" on public.sub_office_election_results
  for all using (public.is_editor_or_admin());

delete from public.sub_office_election_results;

